// 1. Create a template.html file with a placeholder in a <script> tag.
//    Save this as template.html in the same directory.

/* template.html */
<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <title>Injection Test</title>
</head>
<body>
  <h1>Before injection</h1>
  <script>
    /*INJECT_JS*/
  </script>
  <h1>After injection</h1>
</body>
</html>


// 2. Create a Node script that reads template.html, injects JS content containing a `$'` sequence, and writes the result.
//    Save this as inject.js in the same directory.

/* inject.js */
const fs = require('fs');

// Read the HTML template.
const template = fs.readFileSync('template.html', 'utf8');

// JS we want to inject. Notice the $' sequence in the string literal.
const maliciousJs = `console.log("This is a test: $'");`;

// Perform a simple string replace, not using a function or RegExp.
const result = template.replace('/*INJECT_JS*/', maliciousJs);

// Write the output to output.html
fs.writeFileSync('output.html', result);
console.log('Wrote output.html');


